  Tool("Соединиться",async(_,_)=>await ConnectSelected(),true);cancelConnect=Tool("Отключиться",(_,_)=>Disconnect());Tool("Новое соединение",(_,_)=>EditEntry(null),true);Tool("Удалить",(_,_)=>DeleteSelected());tools.Items.Add(new ToolStripSeparator());Tool("Управление",(_,_)=>SetMode("Управление"),true);Tool("Просмотр",(_,_)=>SetMode("Просмотр"),true);Tool("Передача файлов",(_,_)=>SetMode("Передача файлов"));Tool("Текстовый чат",(_,_)=>SetMode("Текстовый чат"));tools.Items.Add(new ToolStripSeparator());Tool("Новая папка",(_,_)=>NewFolder());Tool("Свойства",(_,_)=>EditEntry(SelectedEntry()),true);var find=new ToolStripTextBox{AutoSize=false,Width=180,ToolTipText="Поиск компьютеров"};find.TextChanged+=(_,_)=>RefreshComputers(find.Text);tools.Items.Add(new ToolStripLabel("Поиск:"));tools.Items.Add(find);
