  connectionPage=new Panel{Dock=DockStyle.Fill};connectionPage.Controls.Add(browser);sessionPage=new Panel{Dock=DockStyle.Fill,Visible=false};BuildSessionPage();var workspace=new Panel{Dock=DockStyle.Fill};workspace.Controls.Add(connectionPage);
