 void BuildSessionPage(){
  sessionTools=new ToolStrip{GripStyle=ToolStripGripStyle.Hidden};ToolStripButton Button(string name,EventHandler action){var b=new ToolStripButton(name);b.Click+=action;sessionTools.Items.Add(b);return b;}
