  monitors.Items.Clear();monitors.Width=150;quality.Items.AddRange(["Экономичный","Стандартный","Высокое качество"]);quality.SelectedIndex=1;quality.Width=155;sessionTools.Items.Add(new ToolStripControlHost(monitors));sessionTools.Items.Add(new ToolStripControlHost(quality));clipboard.Text="Буфер обмена";clipboard.AutoSize=true;sessionTools.Items.Add(new ToolStripControlHost(clipboard));
