 }
 void RefreshDeviceList(){deviceList.Items.Clear();deviceList.Items.AddRange(entries.Cast<object>().ToArray());RefreshFolders();RefreshComputers();}
 void RefreshFolders(){refreshing=true;folders.Nodes.Clear();var root=folders.Nodes.Add("\\");root.Tag="";root.ImageIndex=root.SelectedImageIndex=0;foreach(var path in folderNames.Concat(entries.Select(e=>e.Folder)).Where(p=>p.Length>0).Distinct().Order())AddFolderNode(root,path);root.Expand();folders.SelectedNode=FindFolder(root,currentFolder)??root;refreshing=false;}
 static TreeNode? FindFolder(TreeNode root,string path){if(root.Tag as string==path)return root;foreach(TreeNode node in root.Nodes)if(FindFolder(node,path) is {} match)return match;return null;}
 static void AddFolderNode(TreeNode root,string path){var node=root;string prefix="";foreach(var part in path.Split('/',StringSplitOptions.RemoveEmptyEntries)){prefix=prefix.Length==0?part:prefix+"/"+part;var next=node.Nodes.Cast<TreeNode>().FirstOrDefault(n=>n.Text==part);if(next==null){next=node.Nodes.Add(part);next.Tag=prefix;next.ImageIndex=next.SelectedImageIndex=0;}node=next;}}
 void RefreshComputers(string filter=""){
  refreshing=true;computers.BeginUpdate();computers.Items.Clear();if(filter.Length==0){foreach(TreeNode node in (folders.SelectedNode?.Nodes??new TreeNode().Nodes)){var row=new ListViewItem(node.Text,0){Tag=node};computers.Items.Add(row);}}
  foreach(var entry in entries.Where(e=>(filter.Length>0||e.Folder==currentFolder)&&(filter.Length==0||e.Name.Contains(filter,StringComparison.OrdinalIgnoreCase)||e.Host.Contains(filter,StringComparison.OrdinalIgnoreCase)))){var item=new ListViewItem(entry.Name,1){Tag=entry};item.SubItems.Add(entry.Host);item.SubItems.Add(entry.Port==4899?"По умолчанию":entry.Port.ToString());item.SubItems.Add(entry.Folder);computers.Items.Add(item);}computers.EndUpdate();refreshing=false;
 }
 Bookmark? SelectedEntry()=>computers.SelectedItems.Count==1?computers.SelectedItems[0].Tag as Bookmark:null;
 bool LoadSelected(){if(busy||SelectedEntry() is not {} b)return false;bookmarks.SelectedIndex=entries.IndexOf(b);host.Text=b.Host;port.Value=b.Port;pin.Text=b.Fingerprint;code.Clear();deviceList.SelectedItem=b;status.Text=$"Адрес: {b.Host}   Порт: {b.Port}";return true;}
 void SetMode(string mode){connectionMode=mode;modeText.Text=mode;viewOnly.Checked=mode=="Просмотр";}
 async Task ConnectSelected(){if(busy)return;if(computers.SelectedItems.Count==1&&computers.SelectedItems[0].Tag is TreeNode node){folders.SelectedNode=node;return;}if(!LoadSelected()){await QuickConnect();return;}await Connect();}
 async Task QuickConnect(){if(busy)return;using var dialog=new ConnectionProperties(null,currentFolder,folderNames);if(dialog.ShowDialog(this)!=DialogResult.OK)return;var b=dialog.Result!;host.Text=b.Host;port.Value=b.Port;pin.Text=b.Fingerprint;code.Clear();await Connect();}
 void EditEntry(Bookmark? entry){if(busy)return;using var dialog=new ConnectionProperties(entry,currentFolder,folderNames);if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{if(entry!=null)entries.Remove(entry);entries.Add(dialog.Result!);PersistBook();}catch(Exception e){status.Text=e.Message;}}
 void PersistBook(){File.WriteAllText(Path.Combine(folder,"addressbook.json"),JsonSerializer.Serialize(entries));File.WriteAllText(Path.Combine(folder,"folders.json"),JsonSerializer.Serialize(folderNames));RefreshBookmarks();}
 void DeleteSelected(){if(busy)return;if(SelectedEntry()!=null){DeleteBookmark();return;}if(computers.SelectedItems.Count==1&&computers.SelectedItems[0].Tag is TreeNode node&&node.Tag is string path){if(entries.Any(e=>e.Folder==path||e.Folder.StartsWith(path+"/"))){MessageBox.Show(this,"Сначала переместите или удалите соединения из папки.");return;}folderNames.RemoveAll(p=>p==path||p.StartsWith(path+"/"));PersistBook();}}
 void RenameEntry(){if(SelectedEntry() is {} entry)EditEntry(entry);}
 void NewFolder(){if(busy)return;var name=Ui.Ask(this,"Новая папка","Имя папки");if(string.IsNullOrWhiteSpace(name))return;if(name.IndexOfAny(['/','\\',':'])>=0){MessageBox.Show(this,"Имя не должно содержать /, \\ или :");return;}folderNames.Add(currentFolder.Length==0?name:currentFolder+"/"+name);PersistBook();}
 void SortEntries(int column){entries.Sort((a,b)=>column switch{1=>StringComparer.OrdinalIgnoreCase.Compare(a.Host,b.Host),2=>a.Port.CompareTo(b.Port),_=>StringComparer.OrdinalIgnoreCase.Compare(a.Name,b.Name)});RefreshComputers();}
 void RefreshLayoutState(){
  if(IsDisposed)return;bool active=channel!=null&&sessionId.Length>0;browser.Enabled=!busy||active;cancelConnect.Enabled=busy;if(disconnectButton!=null){disconnectButton.Enabled=busy;filesButton.Enabled=active&&granted.HasFlag(Permissions.Files);textButton.Enabled=active&&CanControl;}clipboard.Enabled=active&&granted.HasFlag(Permissions.Clipboard);monitors.Enabled=quality.Enabled=active;
  if(active!=wasConnected){wasConnected=active;if(active){
   remoteClosing=false;remoteWindow=new Form{Text=host.Text+" — "+connectionMode+" | RemoteAdmin",Width=1100,Height=760,MinimumSize=new Size(600,400),StartPosition=FormStartPosition.CenterScreen,Font=new Font("Segoe UI",9),KeyPreview=true,Icon=SystemIcons.Application};remoteWindow.Controls.Add(sessionPage);sessionPage.Visible=true;
   remoteWindow.FormClosing+=(_,e)=>{if(!remoteClosing&&!closing&&channel!=null){e.Cancel=true;Disconnect();}};remoteWindow.KeyDown+=(_,e)=>{if(e.KeyCode==Keys.Escape&&remoteWindow.FormBorderStyle==FormBorderStyle.None){ToggleFullscreen();e.SuppressKeyPress=true;e.Handled=true;}};remoteWindow.Show(this);screen.Focus();if(connectionMode=="Передача файлов")OpenFiles();if(connectionMode=="Текстовый чат")ToggleChat();
  }else{remoteClosing=true;sessionPage.Visible=false;remoteWindow?.Controls.Remove(sessionPage);remoteWindow?.Close();remoteWindow?.Dispose();remoteWindow=null;}}
 }
 void ToggleChat(){remoteSplit.Panel2Collapsed=!remoteSplit.Panel2Collapsed;if(!remoteSplit.Panel2Collapsed)outgoing.Focus();}
 void ToggleFullscreen(){if(remoteWindow==null)return;bool full=remoteWindow.FormBorderStyle!=FormBorderStyle.None;remoteWindow.FormBorderStyle=full?FormBorderStyle.None:FormBorderStyle.Sizable;remoteWindow.WindowState=full?FormWindowState.Maximized:FormWindowState.Normal;}
 void SetScale(bool original){originalScale=original;screen.Dock=original?DockStyle.None:DockStyle.Fill;viewport.AutoScrollMinSize=original&&screen.Frame!=null?screen.Frame.Size:Size.Empty;if(original&&screen.Frame!=null)screen.Size=screen.Frame.Size;viewport.AutoScrollPosition=Point.Empty;screen.Invalidate();}
 void UpdateScale(){if(originalScale&&screen.Frame!=null){screen.Size=screen.Frame.Size;viewport.AutoScrollMinSize=screen.Frame.Size;}}
 void FieldError(TextBox field,string message){status.Text=message;MessageBox.Show(this,message,"Проверьте параметры подключения",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 static string ConnectionError(Exception error)=>error switch{System.Security.Authentication.AuthenticationException=>"Ключ сервера не подтверждён или изменился. Проверьте безопасность подключения.",System.Net.Sockets.SocketException=>"Сервер недоступен. Проверьте адрес, порт и VPN.",TimeoutException=>"Превышено время ожидания сервера.",_=>"Подключение завершено: "+error.Message};
 async Task SendChat(){if(channel==null||!granted.HasFlag(Permissions.Chat)||string.IsNullOrWhiteSpace(outgoing.Text))return;var message=outgoing.Text;outgoing.Clear();await Send("chat",new{message});chat.AppendText("Вы: "+message+Environment.NewLine);}
 void ForgetServerKey(){if(busy)return;if(MessageBox.Show(this,"Забыть ключ выбранного сервера? Следующее подключение потребует сверки нового ключа.","Безопасность",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;try{new ServerTrust(folder).Forget(host.Text,(int)port.Value);for(int i=0;i<entries.Count;i++)if(entries[i].Host.Equals(host.Text,StringComparison.OrdinalIgnoreCase)&&entries[i].Port==(int)port.Value)entries[i]=entries[i] with{Fingerprint=""};pin.Clear();PersistBook();}catch(Exception e){status.Text=e.Message;}}
 void PasteInvitation(){if(busy)return;try{var value=PairingLink.Parse(Clipboard.GetText());host.Text=value.Host;port.Value=value.Port;pin.Text=value.Fingerprint;code.Text=value.Code;_=Connect();}catch(Exception e){MessageBox.Show(this,e.Message,"Приглашение");}}
 void NewConnection()=>EditEntry(null);
 void ExportBook(){using var dialog=new SaveFileDialog{Filter="Адресная книга RemoteAdmin|*.json",FileName="remoteadmin-addressbook.json"};if(dialog.ShowDialog(this)!=DialogResult.OK)return;File.WriteAllText(dialog.FileName,JsonSerializer.Serialize(new AddressBookExport(1,entries.ToArray(),folderNames.ToArray())));}
 void ImportBook(){if(busy)return;using var dialog=new OpenFileDialog{Filter="Адресная книга RemoteAdmin|*.json"};if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{if(new FileInfo(dialog.FileName).Length>2*1024*1024)throw new InvalidDataException("Адресная книга слишком велика");var data=JsonSerializer.Deserialize<AddressBookExport>(File.ReadAllText(dialog.FileName))??throw new InvalidDataException();if(data.Version!=1||data.Entries.Length>5000||data.Folders.Length>1000||data.Entries.Any(e=>e.Port<1||e.Port>65535||string.IsNullOrWhiteSpace(e.Host)||e.Host.Length>255||e.Name.Length>255||e.Folder.Length>500||e.Fingerprint.Length>0&&!ValidPin(e.Fingerprint)))throw new InvalidDataException("Неверный формат адресной книги");foreach(var item in data.Entries)if(!entries.Any(e=>e.Host==item.Host&&e.Port==item.Port&&e.Folder==item.Folder))entries.Add(item);folderNames.AddRange(data.Folders.Where(f=>f.Length>0&&f.Length<500));PersistBook();}catch(Exception e){MessageBox.Show(this,e.Message,"Импорт не выполнен");}}
 static Bitmap ToolbarIcon(string action){
  var icon=new Bitmap(20,20);using var g=Graphics.FromImage(icon);g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
  if(action=="Удалить"){using var pen=new Pen(Color.Firebrick,3);g.DrawLine(pen,4,4,16,16);g.DrawLine(pen,4,16,16,4);return icon;}
  if(action=="Новая папка"){using var original=MakeIcon(true,20);g.DrawImageUnscaled(original,0,0);g.DrawLine(Pens.DarkGreen,12,10,12,18);g.DrawLine(Pens.DarkGreen,8,14,16,14);return icon;}
  if(action=="Текстовый чат"){g.FillRectangle(Brushes.LightGreen,2,3,16,11);g.DrawRectangle(Pens.SeaGreen,2,3,16,11);g.DrawLine(Pens.SeaGreen,5,14,5,18);g.DrawLine(Pens.SeaGreen,5,18,10,14);return icon;}
  if(action=="Передача файлов"){g.DrawLine(Pens.RoyalBlue,6,2,6,17);g.DrawLine(Pens.RoyalBlue,3,5,6,2);g.DrawLine(Pens.RoyalBlue,9,5,6,2);g.DrawLine(Pens.SeaGreen,14,2,14,17);g.DrawLine(Pens.SeaGreen,11,14,14,17);g.DrawLine(Pens.SeaGreen,17,14,14,17);return icon;}
  using(var monitor=MakeIcon(false,20))g.DrawImageUnscaled(monitor,0,0);
  if(action=="Новое соединение"){g.DrawLine(Pens.Green,13,10,13,18);g.DrawLine(Pens.Green,9,14,17,14);}
  else if(action=="Соединиться"){using var pen=new Pen(Color.Goldenrod,2);g.DrawLines(pen,new Point[]{new(11,2),new(7,10),new(13,10),new(9,18)});}
  else if(action=="Свойства"){g.FillEllipse(Brushes.Goldenrod,10,10,9,9);g.DrawEllipse(Pens.SaddleBrown,10,10,9,9);}
  else if(action=="Управление"){g.DrawLine(Pens.Black,10,6,16,14);g.DrawLine(Pens.Black,10,6,10,13);}
  return icon;
 }
 static Bitmap MakeIcon(bool folder,int size){var image=new Bitmap(size,size);using var g=Graphics.FromImage(image);if(folder){using var brush=new SolidBrush(Color.Goldenrod);g.FillRectangle(brush,1,size/3,size-2,size*2/3-2);g.FillRectangle(brush,2,2,size/2,size/3);}else{using var fill=new SolidBrush(Color.LightSkyBlue);g.FillRectangle(fill,2,2,size-4,size*2/3);g.DrawRectangle(Pens.SteelBlue,2,2,size-4,size*2/3);g.DrawLine(Pens.DimGray,size/2,size*2/3,size/2,size-2);g.DrawLine(Pens.DimGray,size/3,size-2,size*2/3,size-2);}return image;}
}
public sealed record AddressBookExport(int Version,Bookmark[] Entries,string[] Folders);
